<?php
namespace App\Policies; use App\Models\{LibraryFine,User}; class LibraryFinePolicy {public function viewAny(User $u):bool{return $u->hasPermission('library_fines.view');} public function view(User $u,LibraryFine $f):bool{return $u->hasPermission('library_fines.view',$f->college_id);} public function create(User $u):bool{return $u->hasPermission('library_fines.create');} public function update(User $u,LibraryFine $f):bool{return $u->hasPermission('library_fines.update',$f->college_id);} public function pay(User $u,LibraryFine $f):bool{return $u->hasPermission('library_fines.pay',$f->college_id);}}
